4. Client Code:The client code (ProxyPatternExample) demonstrates the usage of the Proxy Design Pattern. It creates an Image object, which is actually an instance of ProxyImage. The client invokes the display() method on the proxy. The proxy, in turn, controls access to the real image, ensuring that it is loaded from disk only when needed. Subsequent calls to display() use the cached image in the proxy, avoiding redundant loading and improving performance. Understand this with the help of example:
            C++

    #include <iostream>
#include <string>
using namespace std;

class Image {
public:
    Image(const string& filename) {
        this->filename = filename;
        loadFromDisk();
    }

    void display() {
        cout << "Displaying image: " << filename << endl;
    }

private:
    string filename;
    void loadFromDisk() {
        cout << "Loading " << filename << " from disk" << endl;
    }
};

class ProxyImage {
public:
    ProxyImage(const string& filename) : filename(filename) {}

    void display() {
        if (!image) {
            image = new Image(filename);
        }
        image->display();
    }

private:
    string filename;
    Image* image = nullptr;
};

// Client code
int main() {
    ProxyImage image("example.jpg");

    // Image will be loaded from disk only when display() is called
    image.display();

    // Image will not be loaded again, as it has been cached in the Proxy
    image.display();

    return 0;
}


